package task

import (
	"encoding/json"
	"fmt"
	"os"
	"sync"
)

const tasksFile = "tasks.json"

// Task represents a single todo item.
type Task struct {
	ID          int    `json:"id"`
	Description string `json:"description"`
	Done        bool   `json:"done"`
}

// Store manages loading and saving tasks to a file.
type Store struct {
	mu    sync.Mutex
	tasks []Task
	nextID int
}

// NewStore creates a new TaskStore and loads tasks from the file.
func NewStore() (*Store, error) {
	s := &Store{
		tasks: make([]Task, 0),
		nextID: 1,
	}
	if err := s.loadTasks(); err != nil {
		if os.IsNotExist(err) {
			// File doesn't exist, start with an empty list
			return s, nil
		}
		return nil, fmt.Errorf("failed to load tasks: %w", err)
	}
	s.updateNextID()
	return s, nil
}

// AddTask adds a new task to the store.
func (s *Store) AddTask(description string) (Task, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	task := Task{
		ID:          s.nextID,
		Description: description,
		Done:        false,
	}
	s.tasks = append(s.tasks, task)
	s.nextID++

	if err := s.saveTasks(); err != nil {
		return Task{}, fmt.Errorf("failed to save tasks after adding: %w", err)
	}
	return task, nil
}

// ListTasks returns all tasks, optionally filtered by done status.
func (s *Store) ListTasks(includeDone bool) []Task {
	s.mu.Lock()
	defer s.mu.Unlock()

	if includeDone {
		return s.tasks
	}

	var pendingTasks []Task
	for _, t := range s.tasks {
		if !t.Done {
			pendingTasks = append(pendingTasks, t)
		}
	}
	return pendingTasks
}

// CompleteTask marks a task as done.
func (s *Store) CompleteTask(id int) (Task, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	for i := range s.tasks {
		if s.tasks[i].ID == id {
			if s.tasks[i].Done {
				return s.tasks[i], fmt.Errorf("task %d is already completed", id)
			}
			s.tasks[i].Done = true
			if err := s.saveTasks(); err != nil {
				return Task{}, fmt.Errorf("failed to save tasks after completing: %w", err)
			}
			return s.tasks[i], nil
		}
	}
	return Task{}, fmt.Errorf("task with ID %d not found", id)
}

// loadTasks loads tasks from tasks.json.
func (s *Store) loadTasks() error {
	data, err := os.ReadFile(tasksFile)
	if err != nil {
		return err
	}
	return json.Unmarshal(data, &s.tasks)
}

// saveTasks saves tasks to tasks.json.
func (s *Store) saveTasks() error {
	data, err := json.MarshalIndent(s.tasks, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal tasks: %w", err)
	}
	return os.WriteFile(tasksFile, data, 0644)
}

// updateNextID sets nextID to be one greater than the maximum ID in the current tasks.
func (s *Store) updateNextID() {
	maxID := 0
	for _, t := range s.tasks {
		if t.ID > maxID {
			maxID = t.ID
		}
	}
	s.nextID = maxID + 1
}

package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"strconv"

	"github.com/user/todo-cli/internal/task"
)

const (
	errorInvalidArgs = "invalid arguments"
	exitCodeInvalidArgs = 42
)

type output struct {
	ID     int    `json:"id,omitempty"`
	Status string `json:"status,omitempty"`
	Error  string `json:"error,omitempty"`
	Tasks  []task.Task `json:"tasks,omitempty"`
}

func main() {
	os.Exit(run(os.Args[1:], os.Stdout))
}

func run(args []string, w io.Writer) int {
	store, err := task.NewStore()
	if err != nil {
		printError(w, err.Error())
		return 1
	}

	if len(args) == 0 {
		printError(w, errorInvalidArgs)
		return exitCodeInvalidArgs
	}

	cmd := args[0]
	subArgs := args[1:]

	switch cmd {
	case "add":
		return handleAdd(subArgs, store, w)
	case "list":
		return handleList(store, w)
	case "done":
		return handleDone(subArgs, store, w)
	default:
		printError(w, fmt.Sprintf("unknown command: %s", cmd))
		return exitCodeInvalidArgs
	}
}

func handleAdd(args []string, store *task.Store, w io.Writer) int {
	if len(args) == 0 {
		printError(w, errorInvalidArgs)
		return exitCodeInvalidArgs
	}
	// Join all arguments to form the description, in case it contains spaces
	description := args[0]

	t, err := store.AddTask(description)
	if err != nil {
		printError(w, err.Error())
		return 1
	}
	printJSON(w, output{ID: t.ID, Status: "added"})
	return 0
}

func handleList(store *task.Store, w io.Writer) int {
	tasks := store.ListTasks(false) // Only list pending tasks
	printJSON(w, output{Tasks: tasks})
	return 0
}

func handleDone(args []string, store *task.Store, w io.Writer) int {
	if len(args) == 0 {
		printError(w, errorInvalidArgs)
		return exitCodeInvalidArgs
	}

	id, err := strconv.Atoi(args[0])
	if err != nil {
		printError(w, errorInvalidArgs)
		return exitCodeInvalidArgs
	}

	t, err := store.CompleteTask(id)
	if err != nil {
		printError(w, err.Error())
		return 1
	}
	printJSON(w, output{ID: t.ID, Status: "completed"})
	return 0
}

func printJSON(w io.Writer, data interface{}) {
	encoder := json.NewEncoder(w)
	encoder.SetIndent("", "") // No indent for compact output
	if err := encoder.Encode(data); err != nil {
		// Fallback to plain error if JSON encoding fails
		fmt.Fprintf(w, "{\"error\": \"failed to encode JSON output: %s\"}\n", err)
	}
}

func printError(w io.Writer, errMsg string) {
	printJSON(w, output{Error: errMsg})
}

package task

import (
	"encoding/json"
	"os"
	"testing"
)

const testTasksFile = "test_tasks.json"

func TestMain(m *testing.M) {
	tasksFile = testTasksFile // Redirect to a test-specific file
	code := m.Run()
	os.Remove(testTasksFile) // Clean up after tests
	os.Exit(code)
}

func TestNewStore(t *testing.T) {
	os.Remove(testTasksFile) // Ensure no old test file exists
	s, err := NewStore()
	if err != nil {
		t.Fatalf("NewStore failed: %v", err)
	}

	if len(s.tasks) != 0 {
		t.Errorf("Expected empty tasks on new store, got %d", len(s.tasks))
	}
	if s.nextID != 1 {
		t.Errorf("Expected nextID to be 1, got %d", s.nextID)
	}

	// Test loading from an existing file
	_ = s.AddTask("Task 1")
	_ = s.AddTask("Task 2")

	s2, err := NewStore()
	if err != nil {
		t.Fatalf("NewStore (existing) failed: %v", err)
	}

	if len(s2.tasks) != 2 {
		t.Errorf("Expected 2 tasks after loading, got %d", len(s2.tasks))
	}
	if s2.nextID != 3 {
		t.Errorf("Expected nextID to be 3 after loading, got %d", s2.nextID)
	}
}

func TestAddTask(t *testing.T) {
	os.Remove(testTasksFile)
	s, _ := NewStore()

	desc1 := "Buy groceries"
	t1, err := s.AddTask(desc1)
	if err != nil {
		t.Fatalf("AddTask failed: %v", err)
	}
	if t1.ID != 1 || t1.Description != desc1 || t1.Done != false {
		t.Errorf("Unexpected task 1: %+v", t1)
	}

	desc2 := "Pay bills"
	t2, err := s.AddTask(desc2)
	if err != nil {
		t.Fatalf("AddTask failed: %v", err)
	}
	if t2.ID != 2 || t2.Description != desc2 || t2.Done != false {
		t.Errorf("Unexpected task 2: %+v", t2)
	}

	if len(s.tasks) != 2 {
		t.Errorf("Expected 2 tasks in store, got %d", len(s.tasks))
	}
}

func TestListTasks(t *testing.T) {
	os.Remove(testTasksFile)
	s, _ := NewStore()

	s.AddTask("Task A")
	s.AddTask("Task B")
	s.CompleteTask(1)

	pending := s.ListTasks(false)
	if len(pending) != 1 || pending[0].ID != 2 {
		t.Errorf("Expected 1 pending task (ID 2), got: %+v", pending)
	}

	all := s.ListTasks(true)
	if len(all) != 2 {
		t.Errorf("Expected 2 tasks, got %d", len(all))
	}

	// Test empty list
	os.Remove(testTasksFile)
	s3, _ := NewStore()
	if len(s3.ListTasks(false)) != 0 {
		t.Errorf("Expected empty list for new store, got %d", len(s3.ListTasks(false)))
	}
}

func TestCompleteTask(t *testing.T) {
	os.Remove(testTasksFile)
	s, _ := NewStore()
	s.AddTask("Task to complete")

	// Complete existing task
	completedTask, err := s.CompleteTask(1)
	if err != nil {
		t.Fatalf("CompleteTask failed: %v", err)
	}
	if completedTask.ID != 1 || !completedTask.Done {
		t.Errorf("Expected task 1 to be done, got %+v", completedTask)
	}

	// Try to complete already completed task
	_, err = s.CompleteTask(1)
	if err == nil || err.Error() != "task 1 is already completed" {
		t.Errorf("Expected 'already completed' error, got: %v", err)
	}

	// Try to complete non-existent task
	_, err = s.CompleteTask(99)
	if err == nil || err.Error() != "task with ID 99 not found" {
		t.Errorf("Expected 'task not found' error, got: %v", err)
	}
}

func TestPersistence(t *testing.T) {
	os.Remove(testTasksFile)
	s1, _ := NewStore()
	_ = s1.AddTask("Persistent task 1")
	_ = s1.AddTask("Persistent task 2")
	_ = s1.CompleteTask(1)

	s2, err := NewStore() // Load from file
	if err != nil {
		t.Fatalf("NewStore failed during persistence test: %v", err)
	}

	if len(s2.tasks) != 2 {
		t.Errorf("Expected 2 tasks after reload, got %d", len(s2.tasks))
	}

	if !s2.tasks[0].Done {
		t.Errorf("Expected task 1 to be done after reload")
	}
	if s2.nextID != 3 {
		t.Errorf("Expected nextID to be 3 after reload, got %d", s2.nextID)
	}

	// Add another task after reload
	newlyAdded, _ := s2.AddTask("Newly added task")
	if newlyAdded.ID != 3 {
		t.Errorf("Expected newly added task ID to be 3, got %d", newlyAdded.ID)
	}

	// Verify persistence again after another add
	s3, _ := NewStore()
	if len(s3.tasks) != 3 {
		t.Errorf("Expected 3 tasks after second reload, got %d", len(s3.tasks))
	}
}

func TestErrorHandling(t *testing.T) {
	// Test unmarshalling error on load
	os.WriteFile(testTasksFile, []byte("invalid json"), 0644)
	_, err := NewStore()
	if err == nil {
		t.Errorf("Expected error for invalid JSON, got nil")
	}

	// Ensure task file is created if not exists
	os.Remove(testTasksFile)
	store, err := NewStore()
	if err != nil {
		t.Fatalf("NewStore failed: %v", err)
	}
	_, err = store.AddTask("test")
	if err != nil {
		t.Fatalf("AddTask failed: %v", err)
	}

	// Verify file exists
	_, err = os.Stat(testTasksFile)
	if os.IsNotExist(err) {
		t.Errorf("tasks.json was not created")
	}

}

