package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"testing"

	"github.com/user/todo-cli/internal/task"
)

func TestMain(m *testing.M) {
	// Use a test-specific tasks file for integration tests as well
	task.TestMain(m)
}

func executeCommand(args []string) (string, int) {
	var buf bytes.Buffer
	exitCode := run(args, &buf)
	return strings.TrimSpace(buf.String()), exitCode
}

func TestAddCommand(t *testing.T) {
	os.Remove(task.TestTasksFile) // Clean up before running tests

	// Test adding a task
	out, code := executeCommand([]string{"add", "Buy milk"})
	if code != 0 {
		t.Fatalf("Expected exit code 0, got %d. Output: %s", code, out)
	}

	expected := `{"id":1,"status":"added"}`
	if out != expected {
		t.Errorf("Expected %s, got %s", expected, out)
	}

	// Add another task
